import { defineQuery } from "groq";
import {
  HOME_FEATURED_LIMIT,
  HOME_JOURNAL_LIMIT,
  JOURNAL_NEEDS_ATTENTION_FILTER,
  WORK_NEEDS_ATTENTION_FILTER,
} from "./filters";

/**
 * All GROQ for the site lives here (CLAUDE.md). Result types are generated by `pnpm typegen`
 * into src/sanity/types.ts. Never hand-write them.
 */

// Image projection: asset ref + hotspot/crop for the URL builder, plus LQIP and dimensions.
const image = /* groq */ `{
  ...,
  "lqip": asset->metadata.lqip,
  "dimensions": asset->metadata.dimensions{ width, height, aspectRatio }
}`;

/**
 * Shared media object (src/sanity/schemas/media.ts): an image or a Bunny HLS video.
 * Only the branch for the chosen kind is returned, so a stale hidden field never leaks through.
 */
const media = /* groq */ `{
  kind,
  kind == "image" => { "image": image${image} },
  kind == "video" => {
    "video": video{ playlistUrl, alt, caption, playback, poster${image} }
  }
}`;

// Project cards (WorkListCard): listing visual only.
const workCard = /* groq */ `{
  _id,
  title,
  "slug": slug.current,
  client,
  year,
  services,
  // Short description for the card; the long one is the fallback (cut to two lines).
  summary,
  excerpt,
  listingMedia${media}
}`;

// Work Archive rows (WorkArchiveCard): the three archive visuals.
const workArchiveCard = /* groq */ `{
  _id,
  title,
  "slug": slug.current,
  services,
  excerpt,
  archiveMedia[]${media}
}`;

const journalCard = /* groq */ `{
  _id,
  title,
  "slug": slug.current,
  publishedAt,
  category,
  excerpt,
  coverImage${image}
}`;

/** ClientsSection: client logos from site settings. */
export const CLIENTS_QUERY = defineQuery(
  `*[_type == "siteSettings" && _id == "siteSettings"][0].clients[defined(logo.asset)]{ _key, name, logo }`,
);

/** Home "Our services": the newest project's listing visual per service, as a thumbnail. */
export const SERVICE_THUMBNAILS_QUERY = defineQuery(
  `{
    "brand": *[_type == "work" && "brand" in services && defined(slug.current)] | order(year desc) [0].listingMedia${media},
    "web": *[_type == "work" && "web" in services && defined(slug.current)] | order(year desc) [0].listingMedia${media},
    "digital-products": *[_type == "work" && "digital-products" in services && defined(slug.current)] | order(year desc) [0].listingMedia${media}
  }`,
);

/** About page photos from site settings. */
export const ABOUT_MEDIA_QUERY = defineQuery(
  `*[_type == "siteSettings" && _id == "siteSettings"][0]{
    "gallery": aboutGallery[defined(asset)]${image},
    "principlesImage": aboutPrinciplesImage${image}
  }`,
);

export const SITE_SETTINGS_QUERY = defineQuery(
  `*[_type == "siteSettings" && _id == "siteSettings"][0]`,
);

/** FeaturedWorkSection on the home page: featured projects first, then the newest. */
export const FEATURED_WORK_QUERY = defineQuery(
  `*[_type == "work" && defined(slug.current)] | order(coalesce(featured, false) desc, year desc, _createdAt desc) [0...$limit] ${workCard}`,
);

/** FeaturedWorkSection on a project page: the newest other projects. */
export const RECENT_WORK_QUERY = defineQuery(
  `*[_type == "work" && defined(slug.current) && slug.current != $slug] | order(year desc, _createdAt desc) [0...$limit] ${workCard}`,
);

/** WorkArchiveSection on /work: every project, newest first. */
export const WORK_ARCHIVE_QUERY = defineQuery(
  `*[_type == "work" && defined(slug.current)] | order(year desc, _createdAt desc) ${workArchiveCard}`,
);

/** ServiceOfferingSection: related work for one service, max 2 items (CLAUDE.md). */
export const WORK_BY_SERVICE_QUERY = defineQuery(
  `*[_type == "work" && $service in services && defined(slug.current)] | order(year desc) [0...2] ${workCard}`,
);

export const WORK_SLUGS_QUERY = defineQuery(
  `*[_type == "work" && defined(slug.current)].slug.current`,
);

export const WORK_QUERY = defineQuery(
  `*[_type == "work" && slug.current == $slug][0]{
    _id,
    _updatedAt,
    title,
    "slug": slug.current,
    client,
    year,
    services,
    summary,
    excerpt,
    seo,
    industry,
    deliverables,
    challenge,
    solution,
    outcome,
    results[]{ _key, value, label },
    websiteUrl,
    listingMedia${media},
    heroMedia${media},
    content[]{
      _key,
      _type,
      _type == "mediaFullWidth" => { "media": media${media} },
      _type == "mediaPair" => { "left": left${media}, "right": right${media} }
    }
  }`,
);

/** FeaturedArticlesSection: featured posts first, then the newest. */
export const FEATURED_JOURNAL_QUERY = defineQuery(
  `*[_type == "journal" && defined(slug.current)] | order(coalesce(featured, false) desc, publishedAt desc) [0...$limit] ${journalCard}`,
);

export const ALL_JOURNAL_QUERY = defineQuery(
  `*[_type == "journal" && defined(slug.current)] | order(publishedAt desc) ${journalCard}`,
);

export const JOURNAL_SLUGS_QUERY = defineQuery(
  `*[_type == "journal" && defined(slug.current)].slug.current`,
);

export const JOURNAL_QUERY = defineQuery(
  `*[_type == "journal" && slug.current == $slug][0]{
    _id,
    _updatedAt,
    title,
    "slug": slug.current,
    publishedAt,
    category,
    excerpt,
    seo,
    coverImage${image},
    body[]{ ..., _type == "imageWithAlt" => ${image} }
  }`,
);

/** FeaturedArticlesSection on an article page: the newest other posts. */
export const RECENT_JOURNAL_QUERY = defineQuery(
  `*[_type == "journal" && defined(slug.current) && slug.current != $slug] | order(publishedAt desc) [0...$limit] ${journalCard}`,
);

/**
 * Sitemap (astro.config.mjs): every project and post page, when it last changed and whether
 * it's hidden from search engines (SEO › Hide from search engines).
 */
export const SITEMAP_QUERY = defineQuery(
  `*[_type in ["work", "journal"] && defined(slug.current)]{
    _type,
    "slug": slug.current,
    _updatedAt,
    "noIndex": seo.noIndex == true
  }`,
);

/** Redirects (astro.config.mjs): old project / post slugs, and Site settings › Redirects. */
export const REDIRECTS_QUERY = defineQuery(
  `{
    "content": *[_type in ["work", "journal"] && defined(slug.current)]{
      _type,
      "slug": slug.current,
      previousSlugs
    },
    "manual": *[_type == "siteSettings" && _id == "siteSettings"][0].redirects[]{ from, to, permanent }
  }`,
);

/**
 * Social share images (src/pages/og/[type]/[slug].png.ts): each project and post with the
 * visual its image is built on. Pages that set SEO › Social image don't need one.
 */
export const SOCIAL_IMAGES_QUERY = defineQuery(
  `*[_type in ["work", "journal"] && defined(slug.current) && !defined(seo.image.asset)]{
    _type,
    "slug": slug.current,
    title,
    "visual": select(
      _type == "work" => coalesce(
        select(listingMedia.kind == "video" => listingMedia.video.poster, listingMedia.image),
        select(heroMedia.kind == "video" => heroMedia.video.poster, heroMedia.image)
      ),
      coverImage
    ){ asset, crop, hotspot },
    // A video visual without a poster: the card uses Bunny's thumbnail instead.
    "videoPlaylist": select(
      _type == "work" => coalesce(
        select(listingMedia.kind == "video" => listingMedia.video.playlistUrl),
        select(heroMedia.kind == "video" => heroMedia.video.playlistUrl)
      )
    )
  }`,
);

/**
 * Studio › Work table (src/sanity/components/WorkTable.tsx). Raw perspective: published and
 * draft versions side by side, merged in the component. `home` lists the published projects
 * the home page shows, in the same order as FEATURED_WORK_QUERY.
 */
export const WORK_TABLE_QUERY = defineQuery(
  `{
    "docs": *[_type == "work" && (_id in path("*") || _id in path("drafts.*"))]{
      _id,
      _createdAt,
      _updatedAt,
      title,
      "slug": slug.current,
      client,
      year,
      services,
      featured,
      "noIndex": seo.noIndex == true,
      "needsAttention": ${WORK_NEEDS_ATTENTION_FILTER},
      "thumbnail": select(
        listingMedia.kind == "video" => listingMedia.video.poster,
        listingMedia.image
      ){ asset, crop, hotspot },
      // A video without a poster: the table shows Bunny's thumbnail.
      "thumbnailVideo": select(listingMedia.kind == "video" => listingMedia.video.playlistUrl)
    },
    "home": *[_type == "work" && _id in path("*") && defined(slug.current)]
      | order(coalesce(featured, false) desc, year desc, _createdAt desc) [0...${HOME_FEATURED_LIMIT}]._id
  }`,
);

/**
 * Studio › Journal table (src/sanity/components/JournalTable.tsx). Raw perspective, as the
 * Work table. `home` lists the published posts the home page shows, in the same order as
 * FEATURED_JOURNAL_QUERY.
 */
export const JOURNAL_TABLE_QUERY = defineQuery(
  `{
    "docs": *[_type == "journal" && (_id in path("*") || _id in path("drafts.*"))]{
      _id,
      _createdAt,
      _updatedAt,
      title,
      "slug": slug.current,
      category,
      publishedAt,
      featured,
      "noIndex": seo.noIndex == true,
      "needsAttention": ${JOURNAL_NEEDS_ATTENTION_FILTER},
      "thumbnail": coverImage{ asset, crop, hotspot }
    },
    "home": *[_type == "journal" && _id in path("*") && defined(slug.current)]
      | order(coalesce(featured, false) desc, publishedAt desc) [0...${HOME_JOURNAL_LIMIT}]._id
  }`,
);
